let personalLore=null,loreSaving=false;
function renderLoreMode(){const personal=$('loreModePersonal').checked;$('personalLoreFields').hidden=!personal;$('lorePaidLimits').hidden=!$('lorePaid').checked;$('lorePrice').disabled=!personal||!$('lorePaid').checked;$('loreRequests').disabled=!personal;$('removeLoreKey').disabled=loreSaving||!selectedLoreHasKey();$('removeLorePreset').disabled=loreSaving||!personalLore?.presets.some(p=>p.name===$('lorePresetChoice').value);}
async function loadLoreSettings(){const own=!!loginSession?.playerId;$('loreSettings').hidden=!own;$('loreSignInHint').hidden=own;personalLore=null;$('personalLoreKey').value='';if(!own)return;$('saveLoreButton').disabled=true;$('loreSettingsInfo').textContent='Loading your storyteller...';const token=state.token,owner=loginSession.playerId;try{const settings=await api('/api/lore-settings');if(token!==state.token||owner!==loginSession?.playerId)return;personalLore=settings;$('loreSettingsInfo').textContent=personalLore.hostEnabled?'':'Your host needs to enable OpenRouter before sagas can be generated.';$('personalLoreKey').placeholder=personalLore.hasKey?'Saved - leave blank to keep it':'Paste your key';$('loreKeyHint').textContent=personalLore.hasKey?'Your key is saved privately. Only enter a new key to replace it.':'Stored privately on this server. Only share it with a host you trust.';$('loreModePersonal').checked=!!personalLore.active&&personalLore.hasKey;$('loreModeHost').checked=!$('loreModePersonal').checked;$('lorePresetChoice').innerHTML=personalLore.presets.map(p=>'<option value="'+esc(p.name)+'">'+esc(p.name)+'</option>').join('')+'<option value="__new">New profile</option>';$('lorePresetChoice').value=personalLore.active||personalLore.presets[0]?.name||'__new';fillLorePreset();$('saveLoreButton').disabled=false;}catch(e){$('loreSettingsInfo').textContent='Settings unavailable. '+e.message;}}
function selectedLoreHasKey(){return !!personalLore?.presets.find(p=>p.name===$('lorePresetChoice').value)?.hasKey;}
function fillLorePreset(){const p=personalLore?.presets.find(p=>p.name===$('lorePresetChoice').value);$('personalLoreKey').value='';$('personalLoreKey').placeholder=p?.hasKey?'Saved - leave blank to keep it':'Paste a key for this profile';$('loreKeyHint').textContent=p?.hasKey?'This profile has a saved key. Leave blank to keep it.':'Each profile has its own key, stored privately on this server. Only share it with a host you trust.';$('lorePresetName').value=p?.name||'My saga';$('lorePresetRoute').value=p?.route||'openrouter/free';$('lorePaid').checked=p?.allowPaid||false;$('lorePrice').value=p?.maxPrice||1;$('loreRequests').value=p?.dailyRequests||5;renderLoreMode();}
$('lorePresetChoice').onchange=fillLorePreset;$('loreModeHost').onchange=renderLoreMode;$('loreModePersonal').onchange=renderLoreMode;$('lorePaid').onchange=renderLoreMode;
async function saveLoreSettings(payload){if(payload.key&&location.protocol!=='https:'&&!['localhost','127.0.0.1','[::1]'].includes(location.hostname))throw Error('Use HTTPS or a local connection before sending an API key.');const token=state.token,owner=loginSession?.playerId;const response=await fetch('/api/lore-settings',{method:'POST',headers:{...viewerHeaders(),'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){let d={};try{d=await response.json();}catch{}throw Error(d.error||'Could not save storyteller settings.');}if(token!==state.token||owner!==loginSession?.playerId)return;$('personalLoreKey').value='';await loadLoreSettings();$('loreSaveStatus').textContent=payload.active?'Saved. Your storyteller will be used for future chapters.':'Saved. Your Viking uses the server storyteller.';}
async function changeLore(action){if(loreSaving||!personalLore)return;loreSaving=true;$('loreSaveStatus').textContent='Saving...';for(const button of $('loreSettings').querySelectorAll('button'))button.disabled=true;try{await action();}catch(error){$('loreSaveStatus').textContent=error.message;}finally{loreSaving=false;$('saveLoreButton').disabled=!personalLore;renderLoreMode();}}
$('loreSettings').onsubmit=e=>{e.preventDefault();changeLore(async()=>{if($('loreModeHost').checked){await saveLoreSettings({active:'',presets:personalLore.presets});return;}if(!selectedLoreHasKey()&&!$('personalLoreKey').value.trim())throw Error('Add your OpenRouter key, or choose Server storyteller.');const selected=$('lorePresetChoice').value;const preset={name:$('lorePresetName').value.trim()||'My saga',route:$('lorePresetRoute').value.trim(),allowPaid:$('lorePaid').checked,maxPrice:$('lorePaid').checked?Number($('lorePrice').value):0,dailyRequests:Number($('loreRequests').value)};if(!preset.allowPaid&&!/^openrouter\/free$|^[\w.-]+\/[\w.-]+:free$|^@preset\/[\w.-]+$/.test(preset.route))throw Error('For a paid model, enable paid credits and set your maximum price.');if(!Number.isInteger(preset.dailyRequests)||preset.dailyRequests<1||preset.dailyRequests>20)throw Error('Choose between 1 and 20 requests per day in Advanced options.');if(preset.allowPaid&&(!Number.isFinite(preset.maxPrice)||preset.maxPrice<=0||preset.maxPrice>100))throw Error('Enter a maximum price greater than zero and no more than 100 USD per million tokens.');if(personalLore.presets.some(p=>p.name===preset.name&&p.name!==selected))throw Error('That profile name already exists. Choose it under Saga profile, or use a different name.');await saveLoreSettings({active:preset.name,presets:[...personalLore.presets.filter(p=>p.name!==selected),preset],key:$('personalLoreKey').value.trim(),previousName:selected==='__new'?'':selected});});};
